@json_validate(request_schema='/schema/request/AutoCheck.json',
               response_schema='/schema/response/AutoCheck.json')
class AutoCheck(SparkCommand):
    def execute(self, until_timeout=None):
        return super(AutoCheck, self).execute(until_timeout=until_timeout)


